package com.hau.exam.infrastructure.security;import java.util.*;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.*;import org.springframework.security.web.SecurityFilterChain;@Configuration@EnableMethodSecurity public class SecurityConfig{@Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/actuator/health").permitAll().anyRequest().hasRole("SUBJECT_ADMIN")).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter()))).build();}@Bean JwtDecoder decoder(org.springframework.core.env.Environment e){return NimbusJwtDecoder.withJwkSetUri(Objects.requireNonNull(e.getProperty("spring.security.oauth2.resourceserver.jwt.jwk-set-uri"))).build();}private JwtAuthenticationConverter converter(){var c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(j->List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+j.getClaimAsString("role"))));return c;}}
